    public static boolean unsayable(String s) {
        if (s.charAt(0) != '(') error(s);
        int index = 1;
        int ch = s.charAt(index);

        while (ch != ')') {
            switch(ch) {
                // We can't represent bytes, shorts or arrays yet.
            case 'B': 
            case 'S': 
            case '[': return true;
            case 'F': 
            case 'D': 
            case 'C': 
            case 'I': 
            case 'J': 
            case 'Z': index++; break;
            case 'L': index = s.indexOf(';', index) + 1; break;
            default: error(s);
            }
            ch = s.charAt(index);
        }

        index++;
        ch = s.charAt(index);

        switch(ch) {
        case 'B': 
        case 'S': 
        case '[': return true;
        case 'F': 
        case 'D': 
        case 'V': 
        case 'C':
        case 'I':
        case 'J':
        case 'Z': 
        case 'L': break;
        default: return true;
        }
        return false;
    }

